INSERT INTO changelog_entries(version,title,summary,content,category,published_at,affected_route,created_at,updated_at) SELECT '2.57.0','Premium абонаменти и дневни AI отчети','Месечни и годишни абонаменти, персонални отчети и управление на плащанията.','["Плановете се управляват от администратора. Плащането и управлението на абонамента се извършват сигурно през Stripe.","Premium включва дневен AI отчет по реалните данни в профила, история на отчетите и известие при готов отчет.","Предоставеният от администратор Premium достъп и безплатните известия за запазени процедури се запазват.","Администрацията предлага история на плащанията, абонаменти, webhook журнал и одит на промените по цените."]','feature','2026-09-19','/profile',datetime('now'),datetime('now') WHERE NOT EXISTS (SELECT 1 FROM changelog_entries WHERE version='2.57.0');
